package com.arjunren.leave;
import com.arjunren.leave.domain.*;import com.arjunren.leave.dto.Dtos.LeaveCreate;import com.arjunren.leave.entity.*;import com.arjunren.leave.exception.DomainException;import com.arjunren.leave.repository.*;import com.arjunren.leave.service.LeaveService;import java.time.LocalDate;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.ActiveProfiles;import static org.assertj.core.api.Assertions.*;
@SpringBootTest@ActiveProfiles("test")class LeaveServiceTests{@Autowired UserRepository users;@Autowired EmployeeProfileRepository employees;@Autowired LeaveRequestRepository requests;@Autowired LeaveService service;AppUser manager,employee,otherManager;EmployeeProfile profile;@BeforeEach void setup(){requests.deleteAll();employees.deleteAll();users.deleteAll();manager=users.save(new AppUser("manager@example.com","x","Manager",Role.MANAGER));otherManager=users.save(new AppUser("other@example.com","x","Other",Role.MANAGER));employee=users.save(new AppUser("employee@example.com","x","Employee",Role.EMPLOYEE));profile=employees.save(new EmployeeProfile("E-1",employee,manager,"Engineering",20,10));}@Test void approvalDeductsBalance(){var r=service.request(new LeaveCreate(LeaveType.ANNUAL,LocalDate.now().plusDays(2),LocalDate.now().plusDays(4),"Trip"),employee);service.approve(r.id(),"OK",manager);assertThat(employees.findById(profile.getId()).orElseThrow().getAnnualBalance()).isEqualTo(17);}@Test void overlapIsRejected(){var start=LocalDate.now().plusDays(2);service.request(new LeaveCreate(LeaveType.UNPAID,start,start.plusDays(2),"One"),employee);assertThatThrownBy(()->service.request(new LeaveCreate(LeaveType.SICK,start.plusDays(1),start.plusDays(3),"Two"),employee)).isInstanceOf(DomainException.class).hasMessageContaining("overlaps");}@Test void unrelatedManagerCannotApprove(){var r=service.request(new LeaveCreate(LeaveType.SICK,LocalDate.now().plusDays(2),LocalDate.now().plusDays(2),"Sick"),employee);assertThatThrownBy(()->service.approve(r.id(),null,otherManager)).isInstanceOf(DomainException.class);}@Test void insufficientBalanceIsRejected(){var r=service.request(new LeaveCreate(LeaveType.SICK,LocalDate.now().plusDays(2),LocalDate.now().plusDays(12),"Recovery"),employee);assertThatThrownBy(()->service.approve(r.id(),null,manager)).isInstanceOf(DomainException.class).hasMessageContaining("Insufficient");}}

